# k_in=0, value=6 -> k_out ∈ {0,3,5}
# k_in=3, value=3 -> k_out ∈ {1,3,4,6}
# k_in=4, value=3 -> k_out ∈ {1,3,4,6}
# k_in=4, value=8 -> k_out ∈ {2,4,7}
# k_in=5, value=2 -> k_out ∈ {2,5,7}

# Let me check if there's a formula: k_out = (a * k_in + b) mod n

from collections import defaultdict

def find_formula(k_input_mappings, n):
    """Try to find linear formula k_out = (a*k_in + b) mod n"""
    solutions = defaultdict(set)

    for k_in, k_outs in k_input_mappings.items():
        for k_out in k_outs:
            # Try all a values and solve for b
            for a in range(n):
                if gcd(a, n) == 1:  # a has inverse mod n
                    # k_out = a*k_in + b => b = k_out - a*k_in (mod n)
                    b = (k_out - a * k_in) % n
                    solutions[a].add(b)

    # Find b values that are consistent for most a
    most_common_b = None
    max_count = 0
    for a, bs in solutions.items():
        count = 0
        for k_in, k_outs in k_input_mappings.items():
            for k_out in k_outs:
                b = (k_out - a * k_in) % n
                if b in bs:
                    count += 1
        if count > max_count:
            max_count = count
            most_common_b = (a, b)

    return mostly_common  # return useful formula if found

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

